import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import SimpleButton from '../components/SimpleButton';

const SimpleCAMPreview = () => {
  const navigate = useNavigate();
  const [camFiles, setCamFiles] = useState([]);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState('');
  const [companyData, setCompanyData] = useState(null);

  useEffect(() => {
    // Load company data from localStorage
    const storedCompanyData = localStorage.getItem('companyData');
    if (storedCompanyData) {
      setCompanyData(JSON.parse(storedCompanyData));
    }
  }, []);

  const handleGenerateCAM = async () => {
    if (!companyData) {
      setError('No company data available. Please upload documents first.');
      return;
    }

    setGenerating(true);
    setError('');

    try {
      // Check if it's multi-company data
      if (companyData.is_multi_company && companyData.companies) {
        // Generate CAM for each company
        for (let i = 0; i < companyData.companies.length; i++) {
          const company = companyData.companies[i];
          console.log(`CAM Preview: Generating CAM for company ${i + 1}: ${company.company}`);

          // Generate CAM content for this specific company
          const camContent = generateCAMContent(company, i + 1);

          // Create and download the CAM file
          const blob = new Blob([camContent], { type: 'text/plain' });
          const url = window.URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.download = `CAM_${company.company.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}_Company${i + 1}.txt`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          window.URL.revokeObjectURL(url);

          // Add to CAM files list
          const newCAMFile = {
            id: Date.now() + i,
            filename: link.download,
            company: company.company,
            generated_at: new Date().toISOString(),
            size: blob.size,
            company_index: i + 1
          };
          setCamFiles(prev => [...prev, newCAMFile]);
        }
      } else {
        // Single company CAM generation (existing logic)
        const camContent = generateCAMContent(companyData, 1);

        // Create and download the CAM file
        const blob = new Blob([camContent], { type: 'text/plain' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `CAM_${companyData.company.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.txt`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);

        // Add to CAM files list
        const newCAMFile = {
          id: Date.now(),
          filename: link.download,
          company: companyData.company,
          generated_at: new Date().toISOString(),
          size: blob.size,
          company_index: 1
        };
        setCamFiles([...camFiles, newCAMFile]);
      }

    } catch (err) {
      setError('Failed to generate CAM: ' + err.message);
    } finally {
      setGenerating(false);
    }
  };

  const generateCAMContent = (data, companyNumber) => {
    const currentDate = new Date().toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });

    // Generate unique CAM content based on company-specific data
    const riskFactors = data.ai_analysis?.risk_factors || [];
    const researchData = data.ai_analysis?.research_summary || {};

    return `
CREDIT APPRAISAL MEMORANDUM (CAM) - COMPANY ${companyNumber}
===============================================================

Company: ${data.company}
Industry: ${data.industry || 'N/A'}
File: ${data.file_name || 'N/A'}
Date: ${currentDate}
Generated by: AI Credit Decisioning Engine

EXECUTIVE SUMMARY
=================
This Credit Appraisal Memorandum provides a comprehensive analysis of ${data.company}'s creditworthiness based on financial performance, risk assessment, and industry dynamics. The analysis is specifically tailored to Company ${companyNumber} with unique risk factors and market considerations.

FINANCIAL OVERVIEW
==================
Revenue: ₹${(data.revenue / 10000000).toFixed(2)} Crores
Profit: ₹${(data.profit / 10000000).toFixed(2)} Crores
Total Assets: ₹${(data.assets / 10000000).toFixed(2)} Crores
Total Liabilities: ₹${(data.liabilities / 10000000).toFixed(2)} Crores

Financial Ratios:
- Profit Margin: ${data.financial_ratios?.profit_margin?.toFixed(2) || 'N/A'}%
- Debt-to-Assets Ratio: ${data.financial_ratios?.debt_to_assets?.toFixed(2) || 'N/A'}%
- Return on Assets: ${data.financial_ratios?.return_on_assets?.toFixed(2) || 'N/A'}%
- Working Capital Ratio: ${data.financial_ratios?.working_capital_ratio?.toFixed(2) || 'N/A'}%

COMPANY-SPECIFIC RISK ASSESSMENT
=================================
Risk Score: ${data.ai_analysis?.risk_analysis?.risk_score || 'N/A'}/100
Risk Category: ${data.ai_analysis?.risk_analysis?.risk_category || 'N/A'}
